#include "ui/seti_icons.h"
#include "ui/seti_map.h"       /* generated: the rules, the names, the palette */
#include "ui/seti_data.h"      /* generated by CMake: SETI_SVGS, the SVG text */
#include "ui/icon.h"           /* ui_icon_downscale_rgba */
