/* Declarations only — the implementation is compiled once, in nanosvg_impl.c. */
#include "nanosvg/nanosvg.h"
#include "nanosvg/nanosvgrast.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

/* =========================================================================
 * Name -> icon
 * ========================================================================= */

static int seti_rule_cmp(const void *key, const void *row) {
    return strcmp((const char *)key, ((const SetiRule *)row)->pat);
}

static const SetiRule *seti_find(const SetiRule *rules, usize count, const char *key) {
    return (const SetiRule *)bsearch(key, rules, count, sizeof rules[0], seti_rule_cmp);
}

#define SETI_COUNTOF(a) (sizeof(a) / sizeof((a)[0]))

bool seti_icon_for(const char *name, SetiIcon *out) {
    SetiIcon none = { SETI_ICON_DEFAULT, SETI_COLOR_DEFAULT };
    if (out) *out = none;
    if (!name || !name[0]) return false;

    /* Lower-cased copy. A name too long for the buffer keeps its TAIL, which
     * is all an extension rule reads; no whole-name or prefix rule is that
     * long, so those are skipped rather than matched against a fragment. */
    char low[160];
    usize len = strlen(name);
    bool whole = len < sizeof low;
    const char *src = whole ? name : name + (len - (sizeof low - 1));
    usize n = whole ? len : sizeof low - 1;
    for (usize i = 0; i < n; i++) {
        char c = src[i];
        low[i] = (c >= 'A' && c <= 'Z') ? (char)(c + ('a' - 'A')) : c;
    }
    low[n] = '\0';

    const SetiRule *hit = NULL;
    if (whole) hit = seti_find(SETI_NAME_RULES, SETI_COUNTOF(SETI_NAME_RULES), low);
    /* Leftmost dot first, so the longest suffix wins: ".spec.ts" over ".ts". */
    for (const char *dot = strchr(low, '.'); !hit && dot; dot = strchr(dot + 1, '.')) {
        if (dot[1]) hit = seti_find(SETI_EXT_RULES, SETI_COUNTOF(SETI_EXT_RULES), dot + 1);
    }
    /* A family name carrying a suffix of its own: "Dockerfile.dev",
     * "Makefile.am", "LICENSE-MIT". Only at a separator, and only after the
     * extension had its say — "todo.service.ts" is TypeScript. */
    for (usize i = 0; whole && !hit && i < SETI_COUNTOF(SETI_PREFIX_RULES); i++) {
        usize pl = strlen(SETI_PREFIX_RULES[i].pat);
        if (n > pl && memcmp(low, SETI_PREFIX_RULES[i].pat, pl) == 0 &&
            (low[pl] == '.' || low[pl] == '-' || low[pl] == '_'))
            hit = &SETI_PREFIX_RULES[i];
    }
    if (!hit) return false;
    if (out) *out = (SetiIcon){ hit->icon, hit->color };
    return true;
}

i32 seti_icon_count(void) { return SETI_ICON_COUNT; }

const char *seti_icon_name(u32 icon) {
    return icon < SETI_ICON_COUNT ? SETI_ICON_NAMES[icon] : NULL;
}

/* =========================================================================
 * Colour
 * ========================================================================= */

static Color seti_color_on(u32 rgb, f32 ls) {
    Color c = { (f32)((rgb >> 16) & 0xffu) / 255.0f, (f32)((rgb >> 8) & 0xffu) / 255.0f,
                (f32)(rgb & 0xffu) / 255.0f, 1.0f };

    /* 0.179 is where black and white are equally legible (chrome_legible_on).
     * Below it the surface is the kind Seti was drawn for. */
    if (ls < 0.179f) return c;

    /* The luminance an ink may have and still stand SETI_MIN_CONTRAST off the
     * surface. Scaling all three channels keeps the hue; luminance is monotonic
     * in the scale, so bisect for the lightest shade that qualifies. */
    f32 limit = (ls + 0.05f) / SETI_MIN_CONTRAST - 0.05f;
    if (chrome_luminance(c) <= limit) return c;
    f32 lo = 0.0f, hi = 1.0f;
    for (i32 i = 0; i < 12; i++) {
        f32 k = (lo + hi) * 0.5f;
        if (chrome_luminance((Color){ c.r * k, c.g * k, c.b * k, 1.0f }) <= limit) lo = k;
        else hi = k;
    }
    return (Color){ c.r * lo, c.g * lo, c.b * lo, 1.0f };
}

Color seti_icon_color(u32 color, Color surface) {
    /* Asked once per icon per painted frame, against a surface that changes
     * only with the theme — and on a light one each answer is a bisection of
     * powf calls. The whole palette is worked out when the surface changes
     * and read back after that. */
    static Color memo[SETI_COLOR_COUNT];
    static Color memo_surface;
    static bool  memo_valid;
    if (!memo_valid || surface.r != memo_surface.r || surface.g != memo_surface.g ||
        surface.b != memo_surface.b) {
        f32 ls = chrome_luminance(surface);
        for (u32 i = 0; i < SETI_COLOR_COUNT; i++) memo[i] = seti_color_on(SETI_COLORS[i], ls);
        memo_surface = surface;
        memo_valid = true;
    }
    return memo[color < SETI_COLOR_COUNT ? color : SETI_COLOR_DEFAULT];
}

/* =========================================================================
 * Raster
 * ========================================================================= */

/* How large a glyph is drawn. Seti's artwork leaves wide margins — over the
 * 151 embedded icons, the ink's longer side is 59% of the viewBox at the
 * median and 84% at the largest — because the font it is built into is meant
 * to be set larger than its box. SETI_ZOOM is that enlargement here: 1.3 puts
 * the median glyph at about three quarters of the box, beside a Lucide folder
 * whose ink is five sixths of its own. An icon whose ink would then leave less
 * than SETI_INK_MAX of the box, or less than a clear pixel on each side, is
 * scaled down to fit instead, so nothing is ever clipped. The INK is centred,
 * not the viewBox: four icons (go2, cpp, cu, vite) sit up to 8% off centre in
 * their own artwork. */
#define SETI_ZOOM     1.3f
#define SETI_INK_MAX  0.94f

/* Same reasoning as lucide.c: nanosvg's fixed subsample count thins small
 * shapes, so raster at 2x and area-average down. */
#define SETI_SS_MAX_PX 64
#define SETI_MIN_PX     4
#define SETI_MAX_PX   512

static const SetiSvg *seti_svg(u32 icon) {
    /* Resolved by NAME, once per icon: the map's order is the generator's and
     * the embed's is CMake's, and nothing should depend on the two agreeing. */
    static const SetiSvg *found[SETI_ICON_COUNT];
    static bool looked[SETI_ICON_COUNT];
    if (icon >= SETI_ICON_COUNT) return NULL;
    if (!looked[icon]) {
        looked[icon] = true;
        for (i32 i = 0; i < SETI_SVG_COUNT; i++) {
            if (strcmp(SETI_SVGS[i].name, SETI_ICON_NAMES[icon]) == 0) {
                found[icon] = &SETI_SVGS[i];
                break;
            }
        }
    }
    return found[icon];
}

/* `margin` is the clear border, in pixels of THIS raster, the ink must leave
 * on every side: one pixel of the size being drawn, so an edge texel never
 * carries coverage. */
static u8 *seti_raster_at(const SetiSvg *svg, i32 px, f32 margin) {
    /* nsvgParse() writes into its input, and the source is in .rodata. */
    char *copy = (char *)malloc((usize)svg->size + 1);
    if (!copy) return NULL;
    memcpy(copy, svg->svg, (usize)svg->size);
    copy[svg->size] = '\0';
    NSVGimage *img = nsvgParse(copy, "px", 96.0f);
    free(copy);
    if (!img) return NULL;

    f32 x0 = 0.0f, y0 = 0.0f, x1 = 0.0f, y1 = 0.0f;
    bool any = false;
    for (NSVGshape *s = img->shapes; s; s = s->next) {
        if (!(s->flags & NSVG_FLAGS_VISIBLE)) continue;
        f32 pad = s->stroke.type != NSVG_PAINT_NONE ? s->strokeWidth * 0.5f : 0.0f;
        if (!any || s->bounds[0] - pad < x0) x0 = s->bounds[0] - pad;
        if (!any || s->bounds[1] - pad < y0) y0 = s->bounds[1] - pad;
        if (!any || s->bounds[2] + pad > x1) x1 = s->bounds[2] + pad;
        if (!any || s->bounds[3] + pad > y1) y1 = s->bounds[3] + pad;
        any = true;
    }
    f32 box = fmaxf(img->width, img->height);
    f32 ink = fmaxf(x1 - x0, y1 - y0);
    NSVGrasterizer *rast = any && box > 0.0f && ink > 0.0f ? nsvgCreateRasterizer() : NULL;
    u8 *out = rast ? (u8 *)calloc((usize)px * (usize)px * 4u, 1) : NULL;
    if (!out) {
        if (rast) nsvgDeleteRasterizer(rast);
        nsvgDelete(img);
        return NULL;
    }

    f32 scale = (f32)px / box * SETI_ZOOM;
    f32 room = fminf((f32)px * SETI_INK_MAX, (f32)px - 2.0f * margin);
    if (ink * scale > room) scale = room / ink;
    f32 tx = (f32)px * 0.5f - (x0 + x1) * 0.5f * scale;
    f32 ty = (f32)px * 0.5f - (y0 + y1) * 0.5f * scale;
    nsvgRasterize(rast, img, tx, ty, scale, out, px, px, px * 4);
    nsvgDeleteRasterizer(rast);
    nsvgDelete(img);

    /* Coverage only: whatever the SVG was filled with, the mask is white, and
     * premultiplied white is its own alpha in every channel. */
    for (usize i = 0, count = (usize)px * (usize)px; i < count; i++) {
        u8 *p = out + i * 4u;
        p[0] = p[1] = p[2] = p[3];
    }
    return out;
}

static u8 *seti_render(const SetiSvg *svg, i32 px) {
    if (px > SETI_SS_MAX_PX) return seti_raster_at(svg, px, 1.0f);
    u8 *big = seti_raster_at(svg, px * 2, 2.0f);
    if (!big) return NULL;
    u8 *small = ui_icon_downscale_rgba(big, px * 2, px * 2, px, px);
    free(big);
    return small ? small : seti_raster_at(svg, px, 1.0f);
}

/* The masks. Each icon keeps its own few sizes, so a hit is a scan of one
 * short row; what bounds the memory is ONE byte budget over all of them.
 *
 * One icon can be live at six sizes — the list's, the tab strip's and the
 * docked tab list's, each again on a second display at another scale — so a
 * few slots replaced in rotation would re-rasterise on every request for as
 * long as frames are painted. And slots alone bound nothing: every icon at
 * four sizes near SETI_MAX_PX is hundreds of megabytes. So: eight slots, the
 * least recently used one replaced, and the least recently used mask ANYWHERE
 * dropped until a new one fits the budget. 2 MB is every icon at the 2x list
 * size three times over.
 *
 * Dropping is safe because the renderer never sees these addresses as
 * identities — it is keyed on seti_icon_cache_key() — and copies the pixels
 * into a texture before the draw call returns; a re-raster of the same (icon,
 * px) is byte-identical. */
#define SETI_SIZE_SLOTS   8
#define SETI_CACHE_BUDGET MB(2)
typedef struct {
    i32 px;       /* 0 = empty */
    u8 *rgba;     /* NULL with px set = this size failed; do not retry per frame */
    u64 used;     /* g_clock at the last request */
} SetiSlot;
static SetiSlot g_slots[SETI_ICON_COUNT][SETI_SIZE_SLOTS];
static u64   g_clock;
static usize g_bytes;

static usize seti_mask_bytes(i32 px) { return (usize)px * (usize)px * 4u; }

static void seti_slot_drop(SetiSlot *slot) {
    if (slot->rgba) {
        g_bytes -= seti_mask_bytes(slot->px);
        free(slot->rgba);
    }
    *slot = (SetiSlot){0};
}

usize seti_icon_cache_bytes(void) { return g_bytes; }

const u8 *seti_icon_mask(u32 icon, i32 px) {
    if (icon >= SETI_ICON_COUNT || px < SETI_MIN_PX || px > SETI_MAX_PX) return NULL;
    SetiSlot *slots = g_slots[icon];
    SetiSlot *slot = &slots[0];   /* where a miss goes: an empty slot, else the oldest */
    for (i32 i = 0; i < SETI_SIZE_SLOTS; i++) {
        if (slots[i].px == px) {
            slots[i].used = ++g_clock;
            return slots[i].rgba;
        }
        if (slot->px != 0 && (slots[i].px == 0 || slots[i].used < slot->used)) slot = &slots[i];
    }

    /* Rasterise before making room: a failure must not cost a live mask. */
    const SetiSvg *svg = seti_svg(icon);
    u8 *rgba = svg ? seti_render(svg, px) : NULL;
    usize want = rgba ? seti_mask_bytes(px) : 0;
    seti_slot_drop(slot);
    while (g_bytes + want > SETI_CACHE_BUDGET) {
        SetiSlot *oldest = NULL;
        for (u32 n = 0; n < SETI_ICON_COUNT; n++) {
            for (i32 i = 0; i < SETI_SIZE_SLOTS; i++) {
                SetiSlot *c = &g_slots[n][i];
                if (c->rgba && (!oldest || c->used < oldest->used)) oldest = c;
            }
        }
        if (!oldest) break;
        seti_slot_drop(oldest);
    }
    slot->px = px;
    slot->rgba = rgba;
    slot->used = ++g_clock;
    g_bytes += want;
    return rgba;
}

const void *seti_icon_cache_key(u32 icon, i32 px) {
    /* One address per (icon, size), as icon.c does for its own masks. */
    #define SETI_KEY_PX 256
    static char anchor[SETI_ICON_COUNT][SETI_KEY_PX];   /* .bss, never read */
    if (icon >= SETI_ICON_COUNT) icon = SETI_ICON_DEFAULT;
    if (px < 0) px = 0;
    if (px >= SETI_KEY_PX) px = SETI_KEY_PX - 1;
    return &anchor[icon][px];
    #undef SETI_KEY_PX
}
